import { useState, useRef, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Search, MapPin, ChevronDown, Menu, X, Star,
  Stethoscope, Smile, Sun, Brain, Eye, Bone,
  CheckCircle, ArrowRight,
  Users, Award, Clock, Shield,
  Smartphone, Apple, ChevronRight,
} from 'lucide-react'
import { Button } from '@/components/ui/button'

/* ── Data ─────────────────────────────────────────────────── */

const specialties = [
  { icon: Stethoscope, label: 'Primary Care', desc: 'Annual checkups, sick visits, and preventive care' },
  { icon: Smile, label: 'Dentist', desc: 'Cleanings, fillings, and oral health exams' },
  { icon: Sun, label: 'Dermatologist', desc: 'Skin conditions, acne, and cosmetic consultations' },
  { icon: Brain, label: 'Psychiatrist', desc: 'Mental health evaluations and medication management' },
  { icon: Eye, label: 'Eye Doctor', desc: 'Vision exams, glasses prescriptions, and eye health' },
  { icon: Bone, label: 'Orthopedic Surgeon', desc: 'Joint pain, fractures, and sports injuries' },
]

const suggestions = [
  ...specialties.map(s => ({ type: 'specialty' as const, label: s.label })),
  { type: 'condition' as const, label: 'Back pain' },
  { type: 'condition' as const, label: 'Acne' },
  { type: 'condition' as const, label: 'Anxiety' },
  { type: 'condition' as const, label: 'Allergies' },
  { type: 'condition' as const, label: 'Migraine' },
  { type: 'condition' as const, label: 'Annual physical' },
  { type: 'doctor' as const, label: 'Dr. Sarah Chen' },
  { type: 'doctor' as const, label: 'Dr. James Wilson' },
  { type: 'doctor' as const, label: 'Dr. Maria Rodriguez' },
]

const insurancePlans = [
  'Aetna', 'Blue Cross Blue Shield', 'Cigna', 'UnitedHealthcare',
  'Humana', 'Medicare', 'Medicaid', 'Kaiser Permanente',
]

const steps = [
  {
    num: '01',
    title: 'Search for a provider',
    body: 'Enter your specialty, condition, or doctor name along with your location and insurance. Browse detailed provider profiles with photos, credentials, and office hours.',
    icon: Search,
  },
  {
    num: '02',
    title: 'Choose a time that works',
    body: 'View real-time availability and pick an appointment slot that fits your schedule — including same-day and next-day options.',
    icon: Clock,
  },
  {
    num: '03',
    title: 'Book instantly',
    body: 'Confirm your visit in just a few clicks. Receive instant confirmation and reminders so you never miss an appointment.',
    icon: CheckCircle,
  },
]

const stats = [
  { value: '4.8M+', label: 'Verified patient reviews', icon: Star },
  { value: '12,000+', label: 'Healthcare providers nationwide', icon: Users },
  { value: 'Same-day', label: 'Appointments available daily', icon: Clock },
  { value: '100% free', label: 'For patients — always', icon: Shield },
]

const testimonials = [
  {
    quote: 'I found a great dermatologist near my office and booked a same-day appointment during my lunch break. MedBook made it incredibly easy.',
    name: 'Priya M.',
    location: 'New York, NY',
  },
  {
    quote: 'As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes. Highly recommend!',
    name: 'James T.',
    location: 'Chicago, IL',
  },
  {
    quote: 'I was dreading finding a new dentist, but the verified reviews on MedBook gave me confidence. My appointment was exactly what I needed.',
    name: 'Laura K.',
    location: 'Austin, TX',
  },
]

const appFeatures = [
  'Book and manage appointments anywhere',
  'Get real-time appointment reminders',
  'Access your visit history and provider details',
  'Read and leave verified reviews',
]

const footerLinks = {
  'For Patients': ['Find a Doctor', 'Browse Specialties', 'Read Reviews', 'Insurance Guide'],
  'For Providers': ['List Your Practice', 'Provider Resources', 'Advertise with Us'],
  'Company': ['About MedBook', 'Careers', 'Press', 'Blog', 'Contact Us'],
  'Legal': ['Terms of Service', 'Privacy Policy', 'Accessibility', 'Do Not Sell My Info'],
}

/* ── Animated Counter ───────────────────────────────────── */

function AnimatedStat({ value, label, icon: Icon }: { value: string; label: string; icon: React.ComponentType<{ className?: string }> }) {
  const ref = useRef<HTMLDivElement>(null)
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const node = ref.current
    if (!node) return
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setVisible(true) },
      { threshold: 0.4 }
    )
    obs.observe(node)
    return () => obs.disconnect()
  }, [])

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
      className="text-center"
    >
      <Icon className="w-7 h-7 text-[#FFD930] mx-auto mb-3" />
      <div className="text-3xl md:text-4xl font-extrabold text-white mb-1">
        {visible ? value : ''}
      </div>
      <p className="text-white/70 text-sm md:text-base">{label}</p>
    </motion.div>
  )
}

/* ── Main App ────────────────────────────────────────────── */

export default function App() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [location, setLocation] = useState('')
  const [insurance, setInsurance] = useState('')
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [showInsurance, setShowInsurance] = useState(false)
  const searchRef = useRef<HTMLDivElement>(null)
  const insuranceRef = useRef<HTMLDivElement>(null)

  const filteredSuggestions = searchQuery.length > 0
    ? suggestions.filter(s =>
        s.label.toLowerCase().includes(searchQuery.toLowerCase())
      ).slice(0, 6)
    : suggestions.slice(0, 5)

  const handleSpecialtyClick = useCallback((label: string) => {
    setSearchQuery(label)
    const el = document.getElementById('search-input')
    el?.focus()
    el?.scrollIntoView({ behavior: 'smooth', block: 'center' })
  }, [])

  // close dropdowns when clicking outside
  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) setShowSuggestions(false)
      if (insuranceRef.current && !insuranceRef.current.contains(e.target as Node)) setShowInsurance(false)
    }
    document.addEventListener('mousedown', handleClick)
    return () => document.removeEventListener('mousedown', handleClick)
  }, [])

  useEffect(() => {
    if (mobileMenuOpen) document.body.style.overflow = 'hidden'
    else document.body.style.overflow = ''
    return () => { document.body.style.overflow = '' }
  }, [mobileMenuOpen])

  return (
    <div className="min-h-screen bg-white font-sans overflow-x-hidden">
      {/* ── Header ──────────────────────────────────── */}
      <header className="sticky top-0 z-50 bg-white/95 backdrop-blur-sm border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 md:h-18 flex items-center justify-between">
          <a href="#" className="text-xl md:text-2xl font-extrabold text-[#1B1464] tracking-tight">
            MedBook
          </a>

          <nav className="hidden md:flex items-center gap-8 text-sm font-medium">
            <a href="#" className="text-gray-600 hover:text-[#1B1464] transition-colors">Browse</a>
            <a href="#" className="text-gray-600 hover:text-[#1B1464] transition-colors">Help</a>
            <a href="#" className="text-gray-600 hover:text-[#1B1464] transition-colors">Log In</a>
            <Button className="bg-[#1B1464] hover:bg-[#2D2680] text-white rounded-full px-5 h-9 text-sm">
              Sign Up
            </Button>
          </nav>

          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden p-2 -mr-2 text-[#1B1464]"
            aria-label="Toggle menu"
          >
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>

        <AnimatePresence>
          {mobileMenuOpen && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              className="md:hidden bg-white border-b border-gray-100 overflow-hidden"
            >
              <div className="px-4 py-4 space-y-3">
                <a href="#" className="block py-2 text-gray-700 font-medium" onClick={() => setMobileMenuOpen(false)}>Browse</a>
                <a href="#" className="block py-2 text-gray-700 font-medium" onClick={() => setMobileMenuOpen(false)}>Help</a>
                <a href="#" className="block py-2 text-gray-700 font-medium" onClick={() => setMobileMenuOpen(false)}>Log In</a>
                <Button className="w-full bg-[#1B1464] hover:bg-[#2D2680] text-white rounded-full h-10">
                  Sign Up
                </Button>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </header>

      <main>
        {/* ── Hero + Search ───────────────────────────── */}
        <section className="relative bg-[#1B1464] overflow-hidden">
          <div className="absolute inset-0 opacity-[0.07]"
            style={{ backgroundImage: 'radial-gradient(circle at 25% 60%, #fff 1px, transparent 1px)', backgroundSize: '40px 40px' }} />
          <div className="absolute top-0 right-0 w-[600px] h-[600px] rounded-full bg-[#FFD930] opacity-[0.04] translate-x-1/3 -translate-y-1/3" />

          <div className="relative max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 pt-16 pb-12 md:pt-24 md:pb-16 text-center">
            <motion.h1
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6 }}
              className="text-4xl sm:text-5xl md:text-6xl font-extrabold text-white leading-[1.1] tracking-tight mb-4"
            >
              Find and book the care you need
            </motion.h1>
            <motion.p
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.15 }}
              className="text-base md:text-lg text-white/70 max-w-2xl mx-auto mb-10"
            >
              Search thousands of doctors, dentists, and specialists. Read verified patient reviews.
              Book appointments instantly — even same-day. It's that easy, and always free.
            </motion.p>

            {/* Search Bar */}
            <motion.div
              initial={{ opacity: 0, y: 24 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.3 }}
              className="bg-white rounded-2xl shadow-2xl shadow-black/20 p-3 md:p-4"
            >
              <div className="flex flex-col md:flex-row gap-2 md:gap-0">
                {/* Autocomplete field */}
                <div ref={searchRef} className="relative flex-1 md:border-r border-gray-200 px-3">
                  <label className="block text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1 text-left">
                    Specialty, condition, or doctor
                  </label>
                  <div className="flex items-center">
                    <Search className="w-4 h-4 text-gray-400 mr-2 shrink-0" />
                    <input
                      id="search-input"
                      type="text"
                      value={searchQuery}
                      onChange={e => { setSearchQuery(e.target.value); setShowSuggestions(true) }}
                      onFocus={() => setShowSuggestions(true)}
                      placeholder="Search by condition, specialty, or doctor name"
                      className="w-full py-2.5 text-gray-800 placeholder:text-gray-400 bg-transparent outline-none text-sm md:text-base"
                    />
                  </div>
                  <AnimatePresence>
                    {showSuggestions && (
                      <motion.div
                        initial={{ opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -4 }}
                        transition={{ duration: 0.15 }}
                        className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-xl border border-gray-100 py-2 z-50"
                      >
                        {filteredSuggestions.map((s, i) => (
                          <button
                            key={`${s.label}-${i}`}
                            onClick={() => { setSearchQuery(s.label); setShowSuggestions(false) }}
                            className="w-full text-left px-4 py-2.5 hover:bg-gray-50 flex items-center gap-3 text-sm"
                          >
                            <Search className="w-3.5 h-3.5 text-gray-400 shrink-0" />
                            <span className="text-gray-800">{s.label}</span>
                            <span className="ml-auto text-[10px] font-semibold uppercase tracking-wider text-gray-400 bg-gray-100 rounded-full px-2 py-0.5">
                              {s.type}
                            </span>
                          </button>
                        ))}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>

                {/* Location field */}
                <div className="flex-1 md:border-r border-gray-200 px-3">
                  <label className="block text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1 text-left">
                    Location
                  </label>
                  <div className="flex items-center">
                    <MapPin className="w-4 h-4 text-gray-400 mr-2 shrink-0" />
                    <input
                      type="text"
                      value={location}
                      onChange={e => setLocation(e.target.value)}
                      placeholder="City, state, or zip code"
                      className="w-full py-2.5 text-gray-800 placeholder:text-gray-400 bg-transparent outline-none text-sm md:text-base"
                    />
                  </div>
                </div>

                {/* Insurance dropdown */}
                <div ref={insuranceRef} className="relative flex-1 px-3">
                  <label className="block text-xs font-semibold text-gray-400 uppercase tracking-wider mb-1 text-left">
                    Insurance
                  </label>
                  <button
                    onClick={() => setShowInsurance(!showInsurance)}
                    className="flex items-center w-full py-2.5 text-left text-sm md:text-base"
                  >
                    <Shield className="w-4 h-4 text-gray-400 mr-2 shrink-0" />
                    <span className={insurance ? 'text-gray-800' : 'text-gray-400'}>
                      {insurance || 'Choose your insurance plan'}
                    </span>
                    <ChevronDown className={`w-4 h-4 text-gray-400 ml-auto transition-transform ${showInsurance ? 'rotate-180' : ''}`} />
                  </button>
                  <AnimatePresence>
                    {showInsurance && (
                      <motion.div
                        initial={{ opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -4 }}
                        transition={{ duration: 0.15 }}
                        className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-xl border border-gray-100 py-2 z-50 max-h-60 overflow-y-auto"
                      >
                        {insurancePlans.map(plan => (
                          <button
                            key={plan}
                            onClick={() => { setInsurance(plan); setShowInsurance(false) }}
                            className="w-full text-left px-4 py-2.5 hover:bg-gray-50 text-sm text-gray-800"
                          >
                            {plan}
                          </button>
                        ))}
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>

                {/* Search button */}
                <div className="flex items-center px-2">
                  <Button className="w-full md:w-auto bg-[#FFD930] hover:bg-[#F0C800] text-[#1B1464] font-bold rounded-xl px-8 h-12 text-base shadow-md shadow-yellow-500/20">
                    <Search className="w-4 h-4 mr-2" />
                    Search
                  </Button>
                </div>
              </div>
            </motion.div>

            {/* Trust badges */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.6, delay: 0.6 }}
              className="flex flex-wrap justify-center gap-6 mt-6 text-white/50 text-xs font-medium"
            >
              <span className="flex items-center gap-1.5"><Shield className="w-3.5 h-3.5" /> HIPAA Secure</span>
              <span className="flex items-center gap-1.5"><Star className="w-3.5 h-3.5" /> 4.8M+ Reviews</span>
              <span className="flex items-center gap-1.5"><CheckCircle className="w-3.5 h-3.5" /> Always Free</span>
            </motion.div>
          </div>
        </section>

        {/* ── Popular Specialties ─────────────────────── */}
        <section className="py-16 md:py-24 bg-gray-50">
          <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5 }}
              className="text-center mb-12"
            >
