/* ── Animated Counter ───────────────────────────────────── */

function AnimatedStat({ value, label, icon: Icon }: { value: string; label: string; icon: React.ComponentType<{ className?: string }> }) {
  const ref = useRef<HTMLDivElement>(null)
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const node = ref.current
    if (!node) return
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setVisible(true) },
      { threshold: 0.4 }
    )
    obs.observe(node)
    return () => obs.disconnect()
  }, [])

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, y: 24 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
      className="text-center"
    >
      <Icon className="w-7 h-7 text-[#FFD930] mx-auto mb-3" />
      <div className="text-3xl md:text-4xl font-extrabold text-white mb-1">
        {visible ? value : ''}
      </div>
      <p className="text-white/70 text-sm md:text-base">{label}</p>
    </motion.div>
  )
}

