                  className="group bg-white rounded-2xl p-5 md:p-6 text-left shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 border border-gray-100 hover:border-[#1B1464]/20"
                >
                  <div className="w-12 h-12 rounded-xl bg-[#1B1464]/5 flex items-center justify-center mb-4 group-hover:bg-[#1B1464]/10 transition-colors">
                    <spec.icon className="w-6 h-6 text-[#1B1464]" />
