        {/* ── Testimonials ───────────────────────────── */}
        <section className="py-16 md:py-24 bg-gray-50">
          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5 }}
              className="text-center mb-12"
            >
              <h2 className="text-3xl md:text-4xl font-extrabold text-[#1B1464] mb-3">What Patients Say</h2>
              <p className="text-gray-500 text-base md:text-lg">Over 4.8 million verified reviews from real patients</p>
            </motion.div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {testimonials.map((t, i) => (
                <motion.div
                  key={t.name}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: i * 0.1 }}
                  className="bg-white rounded-2xl p-6 md:p-7 shadow-sm border border-gray-100"
                >
                  <div className="flex gap-1 mb-4">
                    {[...Array(5)].map((_, j) => (
                      <Star key={j} className="w-4 h-4 fill-[#FFD930] text-[#FFD930]" />
                    ))}
                  </div>
                  <p className="text-gray-600 text-sm md:text-base leading-relaxed mb-5">"{t.quote}"</p>
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-[#1B1464]/10 flex items-center justify-center text-[#1B1464] font-bold text-sm">
                      {t.name.split(' ')[0][0]}{t.name.split(' ')[1][0]}
                    </div>
                    <div>
                      <div className="font-semibold text-[#1B1464] text-sm">{t.name}</div>
                      <div className="text-gray-400 text-xs">{t.location}</div>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        </section>

        {/* ── Mobile App Promo ────────────────────────── */}
        <section className="py-16 md:py-24 bg-white">
          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex flex-col md:flex-row items-center gap-10 md:gap-16">
              <motion.div
                initial={{ opacity: 0, x: -30 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.6 }}
                className="flex-1 text-center md:text-left"
              >
                <div className="inline-flex items-center gap-2 bg-[#1B1464]/5 text-[#1B1464] text-sm font-semibold px-4 py-2 rounded-full mb-5">
                  <Smartphone className="w-4 h-4" />
                  Mobile App
                </div>
                <h2 className="text-3xl md:text-4xl font-extrabold text-[#1B1464] mb-4">Your health, in your pocket</h2>
                <p className="text-gray-500 text-base md:text-lg mb-6 leading-relaxed">
                  Download the MedBook app to search for doctors, manage appointments, and get reminders — all on the go.
                </p>

                <ul className="space-y-3 mb-8">
                  {appFeatures.map((feat, i) => (
                    <li key={i} className="flex items-center gap-3 text-sm md:text-base text-gray-700">
                      <CheckCircle className="w-5 h-5 text-[#10B981] shrink-0" />
