                    </li>
                  ))}
                </ul>

                <div className="flex flex-col sm:flex-row gap-3 justify-center md:justify-start">
                  <button className="inline-flex items-center justify-center gap-2 bg-black text-white rounded-xl px-6 py-3 text-sm font-semibold hover:bg-gray-900 transition-colors">
                    <Apple className="w-5 h-5" />
                    <div className="text-left">
                      <div className="text-[10px] font-normal opacity-70 leading-none">Download on the</div>
                      <div className="text-sm leading-none">App Store</div>
                    </div>
                  </button>
                  <button className="inline-flex items-center justify-center gap-2 bg-black text-white rounded-xl px-6 py-3 text-sm font-semibold hover:bg-gray-900 transition-colors">
                    <Smartphone className="w-5 h-5" />
                    <div className="text-left">
                      <div className="text-[10px] font-normal opacity-70 leading-none">Get it on</div>
                      <div className="text-sm leading-none">Google Play</div>
                    </div>
                  </button>
                </div>
              </motion.div>

              <motion.div
                initial={{ opacity: 0, x: 30 }}
                whileInView={{ opacity: 1, x: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.6 }}
                className="flex-1 flex justify-center"
              >
                <div className="relative w-64 h-[460px] bg-[#1B1464] rounded-[2.5rem] p-3 shadow-2xl">
                  <div className="w-full h-full bg-white rounded-[2rem] overflow-hidden flex flex-col">
                    <div className="bg-[#1B1464] h-16 flex items-center justify-center text-white font-bold text-sm">
                      MedBook
                    </div>
                    <div className="flex-1 p-4 space-y-3">
                      {specialties.slice(0, 3).map(s => (
                        <div key={s.label} className="flex items-center gap-2.5 p-2.5 bg-gray-50 rounded-lg">
                          <div className="w-8 h-8 rounded-lg bg-[#1B1464]/5 flex items-center justify-center">
                            <s.icon className="w-4 h-4 text-[#1B1464]" />
                          </div>
                          <span className="text-xs font-semibold text-gray-700">{s.label}</span>
                          <ChevronRight className="w-3.5 h-3.5 text-gray-400 ml-auto" />
